\sheettitle{Fiche 3}{Paramètres de dispersion et concentration -- ÉNONCÉ}{Badr ABOUFARASSE, PhD. -- Année universitaire 2026--2027}

\exercise{Exercice 1 -- Écart absolu moyen, variance et écart-type}
On observe la série suivante :
\begin{center}
\begin{tabular}{c|rrrrr}
$x_i$&2&4&7&12&15\\\hline
$n_i$&4&2&5&7&2
\end{tabular}
\end{center}
\begin{enumerate}
\item Calculer la moyenne.
\item Calculer l'écart absolu moyen $e=\frac1N\sum n_i|x_i-\bar x|$.
\item Calculer la variance $V=\frac1N\sum n_i(x_i-\bar x)^2$ et l'écart-type $\sigma=\sqrt V$.
\item Calculer l'étendue et le coefficient de variation $CV=\sigma/\bar x$.
\end{enumerate}

\exercise{Exercice 2 -- Dispersion d'une distribution groupée}
Reprendre la distribution des 210 clients de la fiche 2.
\begin{enumerate}
\item Compléter un tableau contenant $c_i$, $n_ic_i$, $c_i^2$ et $n_ic_i^2$.
\item Calculer la variance et l'écart-type à l'aide de $V=\overline{x^2}-\bar x^2$.
\item Calculer le coefficient de variation.
\item Calculer l'écart interquartile et commenter ce qu'il mesure par rapport à l'écart-type.
\end{enumerate}

\exercise{Exercice 3 -- Médiale, courbe de Lorenz et indice de Gini}
On étudie des salaires mensuels groupés :
\begin{center}
\begin{tabular}{lrrrr}
\toprule
Classe (centaines d'euros)&$[10,20[$&$[20,30[$&$[30,40[$&$[40,60[$\\\midrule
Effectif $n_i$&20&30&30&20\\\bottomrule
\end{tabular}
\end{center}
\begin{enumerate}
\item Calculer les centres, les masses $n_ic_i$, les masses relatives et leurs cumuls.
\item Déterminer la médiale $MI$, valeur qui partage la masse totale en deux parties égales.
\item Construire les points de la courbe de Lorenz.
\item Calculer l'indice de Gini par la méthode des trapèzes et interpréter le degré de concentration selon l'échelle utilisée dans le cours.
\end{enumerate}

\end{document}

