\sheettitle{Fiche 3}{Paramètres de dispersion et concentration -- CORRIGÉ DÉTAILLÉ}{Badr ABOUFARASSE, PhD. -- Année universitaire 2026--2027}

\solution{Corrigé -- Exercice 1}
\[
N=4+2+5+7+2=20,\qquad \sum n_ix_i=165,
\]
\[
\bar x=165/20=\boxed{8,25}.
\]
Tableau des écarts :
\begin{center}\small
\begin{tabular}{rrrrrr}
\toprule
$x_i$&$n_i$&$|x_i-8,25|$&$n_i|x_i-8,25|$&$(x_i-8,25)^2$&$n_i(x_i-8,25)^2$\\\midrule
2&4&6,25&25,00&39,0625&156,25\\
4&2&4,25&8,50&18,0625&36,125\\
7&5&1,25&6,25&1,5625&7,8125\\
12&7&3,75&26,25&14,0625&98,4375\\
15&2&6,75&13,50&45,5625&91,125\\\midrule
Total&&&79,50&&389,75\\\bottomrule
\end{tabular}
\end{center}
Donc
\[
e=79,5/20=\boxed{3,975},\qquad V=389,75/20=\boxed{19,4875},
\]
\[
\sigma=\sqrt{19,4875}=\boxed{4,414}.
\]
L'étendue vaut $15-2=13$. Le coefficient de variation vaut
\[
CV=\frac{4,414}{8,25}=0,5351\approx\boxed{53,5\%}.
\]

\solution{Corrigé -- Exercice 2}
Avec les centres $c_i=12,16,22,28,32,5,37,5,42,5,47,5,52,5$ :
\begin{center}\scriptsize
\begin{tabular}{rrrrr}
\toprule
$c_i$&$n_i$&$n_ic_i$&$c_i^2$&$n_ic_i^2$\\\midrule
12&4&48&144&576\\
16&12&192&256&3072\\
22&32&704&484&15488\\
28&32&896&784&25088\\
32,5&60&1950&1056,25&63375\\
37,5&35&1312,5&1406,25&49218,75\\
42,5&25&1062,5&1806,25&45156,25\\
47,5&5&237,5&2256,25&11281,25\\
52,5&5&262,5&2756,25&13781,25\\\midrule
Total&210&6665&&227036,5\\\bottomrule
\end{tabular}
\end{center}
\[
\bar x=6665/210=31,7381,
\]
\[
V=\frac{227036,5}{210}-(31,7381)^2=1081,1262-1007,3067=\boxed{73,8195}.
\]
\[
\sigma=\sqrt{73,8195}=\boxed{8,592\ \text{euros}},\qquad CV=8,592/31,738=\boxed{27,07\%}.
\]
Avec $Q_1=26,56$ et $Q_3=37,50$ :
\[
IQR=Q_3-Q_1=\boxed{10,94\ \text{euros}}.
\]
L'écart-type utilise toutes les observations (approchées par les centres) ; l'écart interquartile mesure l'étalement de la moitié centrale de la distribution.

\solution{Corrigé -- Exercice 3}
Centres : $15,25,35,50$. Les masses sont :
\[
20(15)=300,\quad30(25)=750,\quad30(35)=1050,\quad20(50)=1000.
\]
La masse totale vaut $S=3100$.
\begin{center}\small
\begin{tabular}{lrrrr}
\toprule
Classe&$[10,20[$&$[20,30[$&$[30,40[$&$[40,60[$\\\midrule
$n_i$&20&30&30&20\\
$c_i$&15&25&35&50\\
$n_ic_i$&300&750&1050&1000\\
Population cumulée (\%)&20&50&80&100\\
Masse cumulée (\%)&9,68&33,87&67,74&100\\\bottomrule
\end{tabular}
\end{center}

\textbf{Médiale.} La demi-masse vaut $S/2=1550$. Avant la classe $[30,40[$, la masse cumulée est $1050$ ; la masse de cette classe est $1050$ :
\[
MI=30+10\frac{1550-1050}{1050}=\boxed{34,76}.
\]

\textbf{Lorenz.} Les points sont
\[
(0,0),\ (0,2,0,0968),\ (0,5,0,3387),\ (0,8,0,6774),\ (1,1).
\]
\begin{center}
\begin{tikzpicture}
\begin{axis}[width=.72\linewidth,height=6cm,xmin=0,xmax=1,ymin=0,ymax=1,xlabel={Part cumulée de population},ylabel={Part cumulée de masse},grid=major,legend pos=north west]
\addplot[mark=*] coordinates {(0,0)(.2,.096774)(.5,.338710)(.8,.677419)(1,1)};\addlegendentry{Lorenz}
\addplot[dashed] coordinates {(0,0)(1,1)};\addlegendentry{Égalité parfaite}
\end{axis}
\end{tikzpicture}
\end{center}
L'aire sous la courbe, par trapèzes, vaut
\[
A=0,39516.
\]
Donc
\[
G=1-2A=1-0,79032=\boxed{0,20968=20,97\%}.
\]
Selon l'échelle indicative du cours, la concentration est de niveau \textbf{moyen} (un peu au-dessus de 20\%).

\end{document}

